param([Parameter(Mandatory=$true)][int]$RootPid,[int]$DurationSeconds=20,[int]$IntervalMilliseconds=1000,[string]$OutFile="metatron-windows-metrics.json")
$ErrorActionPreference='Stop'
function Get-Tree([int]$Pid){$all=Get-CimInstance Win32_Process;$map=@{};foreach($p in $all){$k=[int]$p.ParentProcessId;if(-not $map.ContainsKey($k)){$map[$k]=@()};$map[$k]+=[int]$p.ProcessId};$q=New-Object Collections.Generic.Queue[int];$q.Enqueue($Pid);$seen=@{};$ids=@();while($q.Count){$x=$q.Dequeue();if($seen[$x]){continue};$seen[$x]=$true;$ids+=$x;if($map[$x]){foreach($c in $map[$x]){$q.Enqueue($c)}}};return $ids}
$logical=[int](Get-CimInstance Win32_ComputerSystem).NumberOfLogicalProcessors;if($logical-lt1){$logical=1};$rows=@();$count=[math]::Max(1,[math]::Ceiling(($DurationSeconds*1000)/$IntervalMilliseconds))
for($i=0;$i-lt$count;$i++){$ids=Get-Tree $RootPid;$ws=0L;$private=0L;$pws=0L;$cpu=0.0;$perf=@(Get-CimInstance Win32_PerfFormattedData_PerfProc_Process -ErrorAction SilentlyContinue);foreach($id in $ids){try{$p=Get-Process -Id $id -ErrorAction Stop;$ws+=$p.WorkingSet64;$private+=$p.PrivateMemorySize64;$cpu+=[double]$p.CPU}catch{};$q=$perf|?{[int]$_.IDProcess-eq$id}|select -First 1;if($q){$pws+=[long]$q.WorkingSetPrivate}};$mem=Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory;$gs=0.0;$gd=0.0;$g3d=0.0;$gmem=$false;$geng=$false;try{$sh=(Get-Counter '\GPU Process Memory(*)\Shared Usage').CounterSamples;$de=(Get-Counter '\GPU Process Memory(*)\Dedicated Usage').CounterSamples;foreach($id in $ids){$pat="pid_$id(_|$)";$gs+=(($sh|?{$_.InstanceName-match$pat}|Measure CookedValue -Sum).Sum);$gd+=(($de|?{$_.InstanceName-match$pat}|Measure CookedValue -Sum).Sum)};$gmem=$true}catch{};try{$eg=(Get-Counter '\GPU Engine(*)\Utilization Percentage').CounterSamples;foreach($id in $ids){$pat="pid_$id(_|$)";$g3d+=(($eg|?{$_.InstanceName-match$pat -and $_.InstanceName-match'engtype_3D'}|Measure CookedValue -Sum).Sum)};$g3d=[math]::Min(100,[double]$g3d);$geng=$true}catch{};$rows+=[pscustomobject]@{ts=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();process_count=$ids.Count;process_ids=$ids;working_set_mib=[math]::Round($ws/1MB,2);private_working_set_mib=[math]::Round($pws/1MB,2);private_bytes_mib=[math]::Round($private/1MB,2);process_cpu_seconds=[math]::Round($cpu,3);logical_processors=$logical;system_available_mib=[double]$mem.AvailableMBytes;system_committed_mib=[math]::Round([double]$mem.CommittedBytes/1MB,2);system_commit_limit_mib=[math]::Round([double]$mem.CommitLimit/1MB,2);gpu_shared_mib=if($gmem){[math]::Round($gs/1MB,2)}else{$null};gpu_dedicated_mib=if($gmem){[math]::Round($gd/1MB,2)}else{$null};gpu_3d_percent=if($geng){[math]::Round($g3d,2)}else{$null}};Start-Sleep -Milliseconds $IntervalMilliseconds}
@{schema=2;root_pid=$RootPid;duration_seconds=$DurationSeconds;interval_ms=$IntervalMilliseconds;samples=$rows}|ConvertTo-Json -Depth 7|Set-Content -Encoding UTF8 $OutFile
